memories = [
    {"ns": ("user", "u1"), "type": "preference", "text": "Prefers Python examples", "status": "active"},
    {"ns": ("user", "u2"), "type": "preference", "text": "Prefers TypeScript examples", "status": "active"},
    {"ns": ("user", "u1"), "type": "transient", "text": "Was tired last Friday", "status": "expired"},
]

def recall(user_id, task):
    task_terms = set(task.lower().split())
    chosen = []
    for m in memories:
        if m["ns"] != ("user", user_id) or m["status"] != "active":
            continue
        if m["type"] == "preference" and ("example" in task_terms or "lesson" in task_terms):
            chosen.append(m["text"])
    return chosen

print(recall("u1", "write a lesson with examples"))
print(recall("u2", "write a lesson with examples"))
